#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

#define NAME "cos"
#define REPEATS 3

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total );
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmark results.
*
* @param iterations   number of iterations
* @param elapsed      elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %0.9f\n", elapsed );
	printf( "  rate: %0.9f\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Generates a random number on the interval [-pi, pi].
*
* @return random number
*/
static double rand_double( void ) {
	int r = rand();
	return ( (double)r / ( (double)RAND_MAX + 1.0 ) * 6.28318530718 ) - 3.14159265359;
}

/**
* Runs a benchmark.
*
* @param size        array size
* @param iterations  number of iterations
* @return elapsed time in seconds
*/
static double benchmark( int size, int iterations ) {
	double elapsed;
	double x[ 1000000 ];
	double y[ 1000000 ];
	volatile double sum;
	double t;
	int i;
	int j;

	for ( i = 0; i < size; i++ ) {
		x[ i ] = rand_double();
	}

	sum = 0.0;
	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		for ( j = 0; j < size; j++ ) {
			y[ j ] = cos( x[ j ] );
			sum += y[ j ];
		}
	}
	elapsed = tic() - t;

	if ( sum != sum ) {
		printf( "should not return NaN\n" );
	}
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int sizes[] = { 10, 100, 1000, 10000, 100000, 1000000 };
	int iterations[] = { 100000, 100000, 10000, 1000, 100, 10 };
	int num_sizes = 6;
	int test_count = 0;
	int i;
	int j;

	srand( time( NULL ) );

	print_version();
	for ( i = 0; i < num_sizes; i++ ) {
		for ( j = 0; j < REPEATS; j++ ) {
			printf( "# c::%s:contiguous=true,ndims=1,dtype=float64,size=%d\n", NAME, sizes[i] );
			elapsed = benchmark( sizes[i], iterations[i] );
			print_results( iterations[i] * sizes[i], elapsed );
			printf( "ok %d benchmark finished\n", ++test_count );
		}
	}
	print_summary( test_count, test_count );
	return 0;
}

